const input = $input.first().json;

function requiredString(value, name) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`${name} is required`);
  }
  return value.trim();
}

function cleanPath(value, name) {
  const path = requiredString(value, name).replace(/^\/+|\/+$/g, '');
  if (!path) throw new Error(`${name} is required`);
  return path;
}

function siteIdFromUrl(siteUrl) {
  const withoutProtocol = siteUrl.replace(/^https?:\/\//i, '');
  const firstSlash = withoutProtocol.indexOf('/');
  const hostname = firstSlash === -1 ? withoutProtocol : withoutProtocol.substring(0, firstSlash);
  const serverPath = firstSlash === -1 ? '' : withoutProtocol.substring(firstSlash).replace(/\/+$/, '');
  return `${hostname}:${serverPath}:`;
}

// Resolve siteUrl: explicit param wins, then $env fallback
const siteUrl = requiredString(
  input.siteUrl || input.siteUrlEnv || $env.SHAREPOINT_SITE_URL || '',
  'siteUrl'
);

// Accept either 'folderPath' or legacy 'transcriptsPath'
const folderRaw = input.folderPath || input.transcriptsPath;
if (!folderRaw) {
  throw new Error(
    `folderPath is required. Received keys: ${Object.keys(input).join(', ') || '(none)'}. ` +
    `Use 'folderPath' (not 'transcriptsPath') for the library-relative destination folder.`
  );
}
if (!input.fileName) {
  throw new Error(`fileName is required. Received keys: ${Object.keys(input).join(', ') || '(none)'}`);
}
if (!Object.prototype.hasOwnProperty.call(input, 'fileContent')) {
  throw new Error(`fileContent is required. Received keys: ${Object.keys(input).join(', ') || '(none)'}`);
}

const siteId = siteIdFromUrl(siteUrl);

const driveId = $env.SHAREPOINT_DRIVE_ID || '';
if (!driveId) {
  throw new Error('SHAREPOINT_DRIVE_ID env var is required for Graph API upload URL');
}

const contentTypeMap = {
  pdf: 'application/pdf',
  json: 'application/json',
  md: 'text/markdown',
  txt: 'text/plain',
  csv: 'text/csv',
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  zip: 'application/zip',
};

let fileList = [];
if (Array.isArray(input.files) && input.files.length > 0) {
  fileList = input.files;
} else if (input.fileName) {
  fileList = [{
    fileName: input.fileName,
    fileContent: input.fileContent,
    contentType: input.contentType,
    encoding: input.encoding,
    folderPath: folderRaw,
  }];
}

const results = [];
for (const file of fileList) {
  const fileName = requiredString(file.fileName, 'fileName');
  if (!Object.prototype.hasOwnProperty.call(file, 'fileContent')) {
    throw new Error(`fileContent is required for ${fileName}`);
  }

  const folderPath = cleanPath(file.folderPath || folderRaw, 'folderPath');
  const rawContent = String(file.fileContent ?? '');
  const encoding = (file.encoding || input.encoding || 'auto').toLowerCase();
  const stripped = rawContent.replace(/\s/g, '');
  const looksBase64 = /^[A-Za-z0-9+/]+=*$/.test(stripped) && stripped.length > 0 && stripped.length % 4 === 0;
  const isBase64 = encoding === 'base64' || (encoding === 'auto' && looksBase64);
  const buffer = isBase64 ? Buffer.from(stripped, 'base64') : Buffer.from(rawContent, 'utf8');

  const ext = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';
  const mimeType = (file.contentType || input.contentType || contentTypeMap[ext] || 'application/octet-stream').trim();
  const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

  // Graph API PUT upload to the Transcripts drive (NOT the default Documents library)
  // URL: /drives/{driveId}/root:/{folderPath}/{fileName}:/content
  const encodedPath = `${folderPath}/${fileName}`.split('/').map(encodeURIComponent).join('/');
  const uploadUrl = `https://graph.microsoft.com/v1.0/drives/${driveId}/root:/${encodedPath}:/content`;

  results.push({
    json: { fileName, folderPath, uploadUrl, siteUrl, siteId, contentType: mimeType },
    binary: { data: binaryData },
  });
}

return results;

const uploadResults = $input.all();
let errorCount = 0;
const results = [];

for (const item of uploadResults) {
  const data = item.json;

  if (data.error) {
    errorCount++;
    const errMsg =
      typeof data.error === 'object'
        ? data.error.message || data.error.description || JSON.stringify(data.error)
        : String(data.error);
    results.push({ success: false, fileName: data.name || null, error: errMsg });
    continue;
  }

  if (!data.id) {
    errorCount++;
    results.push({
      success: false,
      fileName: data.name || null,
      error: 'No DriveItem id in response. Raw: ' + JSON.stringify(data).slice(0, 300),
    });
    continue;
  }

  results.push({
    success: true,
    fileId: data.id,
    fileName: data.name,
    webUrl: data.webUrl || null,
    size: data.size || null,
    lastModified: data.lastModifiedDateTime || null,
  });
}

const totalFiles = results.length;
const successCount = totalFiles - errorCount;

return [
  {
    json: {
      success: errorCount === 0,
      totalFiles,
      successCount,
      errorCount,
      results,
      ...(errorCount > 0
        ? {
            error:
              errorCount === 1
                ? results.find((r) => !r.success).error
                : `${errorCount} of ${totalFiles} files failed to upload`,
          }
        : {}),
    },
  },
];
